class Solution:
    def findShortestSubArray(self, nums):
        first = {}
        count = {}
        degree = 0
        best = 0
        for i, x in enumerate(nums):
            if x not in first:
                first[x] = i
            count[x] = count.get(x, 0) + 1
            length = i - first[x] + 1
            if count[x] > degree:
                degree = count[x]
                best = length
            elif count[x] == degree:
                best = min(best, length)
        return best

